class Solution {
    public String encode(List<String> strs) {
        StringBuilder sb = new StringBuilder();
        for (String s : strs) {
            sb.append(s.length()).append('#').append(s);
        }
        return sb.toString();
    }

    public List<String> decode(String str) {
        List<String> result = new ArrayList<>();
        int i = 0;

        while (i < str.length()) {
            int j = i;
            while (str.charAt(j) != '#') {
                j++;
            }

            int len = Integer.parseInt(str.substring(i, j));
            int start = j + 1;
            result.add(str.substring(start, start + len));
            i = start + len;
        }

        return result;
    }
}

class Solution {
    public String encode(List<String> strs) {
        StringBuilder sb = new StringBuilder();
        for (String s : strs) {
            for (char c : s.toCharArray()) {
                if (c == '/' || c == ':') {
                    sb.append('/');
                }
                sb.append(c);
            }
            sb.append(':');
        }
        return sb.toString();
    }

    public List<String> decode(String str) {
        List<String> result = new ArrayList<>();
        StringBuilder current = new StringBuilder();

        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c == '/') {
                i++;
                current.append(str.charAt(i));
            } else if (c == ':') {
                result.add(current.toString());
                current = new StringBuilder();
            } else {
                current.append(c);
            }
        }

        return result;
    }
}

class Solution {
    private static final int HEADER_WIDTH = 4;

    public String encode(List<String> strs) {
        StringBuilder sb = new StringBuilder();
        for (String s : strs) {
            sb.append(String.format("%04d", s.length()));
            sb.append(s);
        }
        return sb.toString();
    }

    public List<String> decode(String str) {
        List<String> result = new ArrayList<>();
        int i = 0;

        while (i < str.length()) {
            int len = Integer.parseInt(str.substring(i, i + HEADER_WIDTH));
            int start = i + HEADER_WIDTH;
            result.add(str.substring(start, start + len));
            i = start + len;
        }

        return result;
    }
}
